1	package agentusage
2	
3	import (
4		"fmt"
5		"reflect"
6		"testing"
7	)
8	
9	// tline is one line to feed a table: which agent and file it belongs to, where
10	// it sits, and its bytes.
11	type tline struct {
12		agent, name string
13		p           pos
14		b           []byte
15	}
16	
17	func parentPos(off int64) pos { return pos{rank: "0", off: off} }
18	
19	// subPos mirrors the rank the plan gives a sub-agent's file.
20	func subPos(id, name string, off int64) pos {
21		return pos{rank: "1" + id + "\x00" + name, off: off}
22	}
23	
24	func pl(off int64, b []byte) tline { return tline{"", "p.jsonl", parentPos(off), b} }
25	
26	func sl(id string, off int64, b []byte) tline {
27		name := "agent-" + id + ".jsonl"
28		return tline{id, name, subPos(id, name, off), b}
29	}
30	
31	// verLine is a usage line carrying a client version.
32	func verLine(ver, id string) []byte {
33		return []byte(fmt.Sprintf(`{"version":%q,"message":{"id":%q,"model":"x","stop_reason":"end_turn","usage":{"input_tokens":1,"output_tokens":1,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}}}`, ver, id))
34	}
35	
36	func tableAgents(subs ...string) []Agent {
37		agents := []Agent{{Main: true}}
38		for _, id := range subs {
39			agents = append(agents, Agent{ID: id})
40		}
41		return agents
42	}
43	
44	// feed builds a table from lines in the order given.
45	func feed(lines []tline) *table {
46		t := newTable()
47		for _, l := range lines {
48			t.addLine(l.agent, l.name, l.p, l.b)
49		}
50		return t
51	}
52	
53	type tableOut struct {
54		Agents   []Agent
55		Diag     Diagnostics
56		Versions []string
57	}
58	
59	// result runs finish and fails if it returned the wrong number of agents, so
60	// a missing implementation fails here instead of panicking on an index.
61	func result(t *testing.T, tb *table, agents []Agent) tableOut {
62		t.Helper()
63		a, d, v := tb.finish(agents)
64		if len(a) != len(agents) {
65			t.Fatalf("finish returned %d agents, want %d", len(a), len(agents))
66		}
67		return tableOut{a, d, v}
68	}
69	
70	// interleavings returns every merge of a and b that keeps each one's own order.
71	func interleavings(a, b []tline) [][]tline {
72		if len(a) == 0 {
73			return [][]tline{append([]tline(nil), b...)}
74		}
75		if len(b) == 0 {
76			return [][]tline{append([]tline(nil), a...)}
77		}
78		var out [][]tline
79		for _, rest := range interleavings(a[1:], b) {
80			out = append(out, append([]tline{a[0]}, rest...))
81		}
82		for _, rest := range interleavings(a, b[1:]) {
83			out = append(out, append([]tline{b[0]}, rest...))
84		}
85		return out
86	}
87	
88	func TestTableOrderFreedom(t *testing.T) {
89		parent := []tline{
90			pl(0, msgLine("m1", "opus", "", 1, 1, 1, 1)),
91			pl(100, msgLine("m2", "opus", "end_turn", 2, 2, 2, 2)),
92			pl(200, msgLine("m1", "opus", "end_turn", 3, 3, 3, 3)),
93		}
94		sub := []tline{
95			sl("a1", 0, msgLine("m1", "sonnet", "end_turn", 5, 5, 5, 5)),
96			sl("a1", 100, msgLine("m3", "sonnet", "end_turn", 7, 7, 7, 7)),
97		}
98		all := interleavings(parent, sub)
99		if len(all) != 10 {
100			t.Fatalf("interleavings = %d, want 10", len(all))
101		}
102		var first tableOut
103		for i, lines := range all {
104			got := result(t, feed(lines), tableAgents("a1"))
105			if i == 0 {
106				first = got
107				if got.Agents[0].Tokens != (Tokens{2, 2, 2, 2}) || got.Agents[0].Messages != 1 {
108					t.Fatalf("parent = %+v, want only m2", got.Agents[0])
109				}
110				if got.Agents[1].Tokens != (Tokens{12, 12, 12, 12}) || got.Agents[1].Messages != 2 {
111					t.Fatalf("a1 = %+v, want m1 (v from a1) + m3", got.Agents[1])
112				}
113				if got.Diag.CrossFileDuplicates != 1 {
114					t.Fatalf("CrossFileDuplicates = %d, want 1", got.Diag.CrossFileDuplicates)
115				}
116				if !reflect.DeepEqual(got.Agents[0].Models, []string{"opus"}) || !reflect.DeepEqual(got.Agents[1].Models, []string{"sonnet"}) {
117					t.Fatalf("models = %v / %v", got.Agents[0].Models, got.Agents[1].Models)
118				}
119				continue
120			}
121			if !reflect.DeepEqual(got, first) {
122				t.Fatalf("interleaving %d differs:\n got %+v\nwant %+v", i, got, first)
123			}
124		}
125	}
126	
127	// The winner is decided by rank, not by arrival: the sub-agent file fed first
128	// still owns the shared message.
129	func TestTableSubAgentFedFirstStillWins(t *testing.T) {
130		tb := feed([]tline{
131			sl("a1", 0, msgLine("m1", "x", "end_turn", 9, 9, 9, 9)),
132			pl(0, msgLine("m1", "x", "end_turn", 1, 1, 1, 1)),
133		})
134		got := result(t, tb, tableAgents("a1"))
135		if got.Agents[0].Messages != 0 || got.Agents[1].Tokens != (Tokens{9, 9, 9, 9}) {
136			t.Fatalf("agents = %+v, want m1 on a1", got.Agents)
137		}
138		if got.Diag.CrossFileDuplicates != 1 {
139			t.Fatalf("CrossFileDuplicates = %d, want 1", got.Diag.CrossFileDuplicates)
140		}
141	}
142	
143	func TestTableThreeFilesShareAMessage(t *testing.T) {
144		lines := []tline{
145			pl(0, msgLine("m1", "x", "end_turn", 1, 1, 1, 1)),
146			sl("a1", 0, msgLine("m1", "x", "end_turn", 2, 2, 2, 2)),
147			sl("a2", 0, msgLine("m1", "x", "end_turn", 3, 3, 3, 3)),
148		}
149		orders := [][]int{{0, 1, 2}, {2, 1, 0}, {1, 2, 0}, {2, 0, 1}}
150		for _, o := range orders {
151			t.Run(fmt.Sprint(o), func(t *testing.T) {
152				var in []tline
153				for _, i := range o {
154					in = append(in, lines[i])
155				}
156				got := result(t, feed(in), tableAgents("a1", "a2"))
157				if got.Diag.CrossFileDuplicates != 2 {
158					t.Fatalf("CrossFileDuplicates = %d, want 2", got.Diag.CrossFileDuplicates)
159				}
160				if got.Agents[0].Messages != 0 || got.Agents[1].Messages != 0 || got.Agents[2].Tokens != (Tokens{3, 3, 3, 3}) {
161					t.Fatalf("agents = %+v, want m1 on the highest rank (a2)", got.Agents)
162				}
163			})
164		}
165	}
166	
167	// Within one file a later offset wins regardless of arrival, and models are
168	// ordered by first position, not by arrival.
169	func TestTableSameFileOrderedByOffset(t *testing.T) {
170		got := result(t, feed([]tline{
171			pl(200, msgLine("m2", "sonnet", "end_turn", 1, 1, 0, 0)),
172			pl(100, msgLine("m1", "opus", "", 1, 1, 0, 0)),
173			pl(300, msgLine("m1", "opus", "end_turn", 4, 4, 0, 0)),
174		}), tableAgents())
175		if want := []string{"opus", "sonnet"}; !reflect.DeepEqual(got.Agents[0].Models, want) {
176			t.Fatalf("Models = %v, want %v", got.Agents[0].Models, want)
177		}
178		if got.Agents[0].Tokens != (Tokens{5, 5, 0, 0}) || got.Agents[0].PartialMessages != 0 {
179			t.Fatalf("agent = %+v, want m1 at offset 300 plus m2", got.Agents[0])
180		}
181		if got.Diag.CrossFileDuplicates != 0 {
182			t.Fatalf("CrossFileDuplicates = %d, want 0", got.Diag.CrossFileDuplicates)
183		}
184	}
185	
186	// Merge = add: for every split point, merging the two halves equals feeding
187	// everything to one table.
188	func TestTableMergeEqualsAdd(t *testing.T) {
189		lines := []tline{
190			pl(0, msgLine("m1", "opus", "", 1, 1, 1, 1)),
191			pl(100, []byte(`not json`)),
192			pl(150, msgLine("", "opus", "end_turn", 1, 2, 3, 4)),
193			pl(200, msgLine("m1", "opus", "end_turn", 3, 3, 3, 3)),
194			pl(300, []byte(`{"type":"queue-operation"}`)),
195			sl("a1", 0, msgLine("m1", "sonnet", "end_turn", 5, 5, 5, 5)),
196			sl("a1", 100, verLine("2.0.0", "m3")),
197			sl("a1", 200, []byte(`{"message":{"id":"n","model":"x"}}`)),
198			sl("a2", 0, msgLine("m1", "haiku", "", 6, 6, 6, 6)),
199			sl("a2", 90, msgLine("", "haiku", "", 7, 7, 7, 7)),
200		}
201		agents := func() []Agent { return tableAgents("a1", "a2") }
202		want := result(t, feed(lines), agents())
203		for k := 0; k <= len(lines); k++ {
204			t.Run(fmt.Sprintf("split=%d", k), func(t *testing.T) {
205				t1, t2 := feed(lines[:k]), feed(lines[k:])
206				t1.merge(t2)
207				if got := result(t, t1, agents()); !reflect.DeepEqual(got, want) {
208					t.Fatalf("merged differs:\n got %+v\nwant %+v", got, want)
209				}
210				// Commutative: merging the other way round gives the same table.
211				u1, u2 := feed(lines[:k]), feed(lines[k:])
212				u2.merge(u1)
