1	package agentusage
2	
3	// msgKey identifies one message of a session. A message with an id is keyed
4	// by the id alone; one without is keyed by where it was read.
5	type msgKey struct {
6		id   string
7		file string
8		off  int64
9	}
10	
11	// entry is the last state seen of one message.
12	type entry struct {
13		agent    int
14		file     string
15		model    string
16		tokens   Tokens
17		stopNull bool
18	}
19	
20	// aggregator folds records into per-agent totals, last line wins per
21	// message id. Agents must be added in a fixed order (parent, then
22	// sub-agents by ID); a message seen in several files goes to the last.
23	type aggregator struct {
24		agents  []Agent
25		diag    Diagnostics
26		entries map[msgKey]*entry
27		order   []msgKey // first appearance, for stable model order
28		seen    map[string]bool
29		version []string // distinct versions, first appearance order
30		// fileIssues counts the capped FileIssue kinds kept per file name.
31		fileIssues map[string]int
32		noID       int            // table entries holding a line without message id
33		spill      map[int]*spill // per agent: no-id lines past maxNoIDEntries
34	}
35	
36	// spill totals the lines that no longer get a table entry.
37	type spill struct {
38		tokens   Tokens
39		messages int
40		partial  int
41		models   modelSet
42	}
43	
44	// newAggregator starts from agents carrying their identity (ID, Main, Type,
45	// State, SpawnDepth); the counters are filled by add and finish.
46	func newAggregator(agents []Agent) *aggregator {
47		return &aggregator{
48			agents: agents, entries: map[msgKey]*entry{}, seen: map[string]bool{},
49			fileIssues: map[string]int{}, spill: map[int]*spill{},
50		}
51	}
52	
53	// addIssue records a skipped line. Unreadable and oversized lines are kept
54	// at most maxFileIssuesPerFile per file (the counters are not capped); the
55	// other kinds occur once per file and are always kept.
56	func (a *aggregator) addIssue(i FileIssue) {
57		if i.Kind == IssueUnreadable || i.Kind == IssueOversized {
58			if a.fileIssues[i.File] >= maxFileIssuesPerFile {
59				return
60			}
61			a.fileIssues[i.File]++
62		}
63		a.diag.Files = append(a.diag.Files, i)
64	}
65	
66	// addLine decodes one line of agent agentIdx's file (file is a base name) and folds it in,
67	// counting what is skipped. Synthetic and ignored lines never count.
68	func (a *aggregator) addLine(agentIdx int, file string, off int64, line []byte) {
69		r, kind := decodeLine(line)
70		if kind != kindUnreadable {
71			a.noteVersion(r.Version)
72		}
73		switch kind {
74		case kindUsage:
75			a.add(agentIdx, file, off, r)
76		case kindNoUsage:
77			a.diag.NoUsage++
78		case kindUnreadable:
79			a.diag.UnreadableLines++
80			a.addIssue(FileIssue{File: file, Offset: off, Kind: IssueUnreadable})
81		case kindIgnored, kindSynthetic:
82		}
83	}
84	
85	// noteVersion records a client version the first time it is seen, up to
86	// maxVersions.
87	func (a *aggregator) noteVersion(v string) {
88		v = sanitizeLabel(v)
89		if v == "" || a.seen[v] || len(a.version) >= maxVersions {
90			return
91		}
92		a.seen[v] = true
93		a.version = append(a.version, v)
94	}
95	
96	// versions returns the distinct versions seen, in order of first appearance.
97	func (a *aggregator) versions() []string { return a.version }
98	
99	// add folds one usage record in. file and off identify the line when the
100	// record has no message id.
101	func (a *aggregator) add(agentIdx int, file string, off int64, r record) {
102		key := msgKey{id: r.MessageID}
103		if r.MessageID == "" {
104			key = msgKey{file: file, off: off}
105			a.diag.NoMessageID++
106			if a.noID >= maxNoIDEntries {
107				a.addSpill(agentIdx, r)
108				return
109			}
110			a.noID++
111		}
112		e, ok := a.entries[key]
113		if !ok {
114			e = &entry{}
115			a.entries[key] = e
116			a.order = append(a.order, key)
117		} else if e.file != file {
118			a.diag.CrossFileDuplicates++
119		}
120		*e = entry{agent: agentIdx, file: file, model: r.Model, tokens: r.Usage, stopNull: r.StopNull}
121	}
122	
123	// addSpill counts a no-id line that gets no table entry.
124	func (a *aggregator) addSpill(agentIdx int, r record) {
125		sp := a.spill[agentIdx]
126		if sp == nil {
127			sp = &spill{}
128			a.spill[agentIdx] = sp
129		}
130		sp.tokens = sp.tokens.Add(r.Usage)
131		sp.messages++
132		if r.StopNull {
133			sp.partial++
134		}
135		sp.models.add(r.Model)
136	}
137	
138	// finish returns the agents with Tokens, Models, Messages and
139	// PartialMessages computed.
140	func (a *aggregator) finish() []Agent {
141		models := make([]modelSet, len(a.agents))
142		for i := range a.agents {
143			a.agents[i].Tokens, a.agents[i].Models = Tokens{}, nil
144			a.agents[i].Messages, a.agents[i].PartialMessages = 0, 0
145		}
146		for _, key := range a.order {
147			e := a.entries[key]
148			ag := &a.agents[e.agent]
149			ag.Tokens = ag.Tokens.Add(e.tokens)
150			ag.Messages++
151			if e.stopNull {
152				ag.PartialMessages++
153			}
154			models[e.agent].add(e.model)
155		}
156		for i, sp := range a.spill {
157			ag := &a.agents[i]
158			ag.Tokens = ag.Tokens.Add(sp.tokens)
159			ag.Messages += sp.messages
160			ag.PartialMessages += sp.partial
161			for _, m := range sp.models.list {
162				models[i].add(m)
163			}
164		}
165		for i := range a.agents {
166			a.agents[i].Models = models[i].list
167		}
168		return a.agents
169	}
