16	
17	func parentPos(off int64) pos { return pos{rank: "0", off: off} }
18	
19	// subPos mirrors the rank the plan gives a sub-agent's file.
20	func subPos(id, name string, off int64) pos {
21		return pos{rank: "1" + id + "\x00" + name, off: off}
22	}
23	
24	func pl(off int64, b []byte) tline { return tline{"", "p.jsonl", parentPos(off), b} }
25	
26	func sl(id string, off int64, b []byte) tline {
27		name := "agent-" + id + ".jsonl"
28		return tline{id, name, subPos(id, name, off), b}
29	}
