31	// verLine is a usage line carrying a client version.
32	func verLine(ver, id string) []byte {
33		return []byte(fmt.Sprintf(`{"version":%q,"message":{"id":%q,"model":"x","stop_reason":"end_turn","usage":{"input_tokens":1,"output_tokens":1,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}}}`, ver, id))
34	}
