59	// result runs finish and fails if it returned the wrong number of agents, so
60	// a missing implementation fails here instead of panicking on an index.
61	func result(t *testing.T, tb *table, agents []Agent) tableOut {
62		t.Helper()
63		a, d, v := tb.finish(agents)
64		if len(a) != len(agents) {
65			t.Fatalf("finish returned %d agents, want %d", len(a), len(agents))
66		}
67		return tableOut{a, d, v}
68	}
