70	// interleavings returns every merge of a and b that keeps each one's own order.
71	func interleavings(a, b []tline) [][]tline {
72		if len(a) == 0 {
73			return [][]tline{append([]tline(nil), b...)}
74		}
75		if len(b) == 0 {
76			return [][]tline{append([]tline(nil), a...)}
77		}
78		var out [][]tline
79		for _, rest := range interleavings(a[1:], b) {
80			out = append(out, append([]tline{a[0]}, rest...))
81		}
82		for _, rest := range interleavings(a, b[1:]) {
83			out = append(out, append([]tline{b[0]}, rest...))
84		}
85		return out
86	}
