func (t *table) addUsage(agent, name string, p pos, r record) {
	key := msgKey{id: r.MessageID}
	if r.MessageID == "" {
		key = msgKey{file: p.rank, off: p.off}
		t.noMessageID++
		if _, ok := t.entries[key]; !ok {
			if t.noID >= maxNoIDEntries {
				t.addSpill(agent, r)
				return
			}
			t.noID++
		}
